<dialog class="{{ $classes }}" id="{{ $id }}-dialog" aria-labelledby="{{ $id }}-title"@if ($hasDescription) aria-describedby="{{ $id }}-description"@endif data-cm-controller="dialog" data-cm-dialog-state="{{ $open ? 'open' : 'closed' }}" data-cm-dialog-dismissible="{{ $dismissible ? 'true' : 'false' }}"@if ($open) open@endif{!! $attributes !!}><div class="cm-dialog__surface"><header class="cm-dialog__header"><h2 class="cm-dialog__title" id="{{ $id }}-title">{{ $header ?? $title }}</h2>@if ($actions !== null)<div class="cm-dialog__actions">{{ $actions }}</div>@endif<button class="cm-dialog__close" type="button" aria-label="{{ $closeLabel }}" data-cm-dialog-close@if (!$dismissible) disabled@endif>×</button></header>@if ($customDescription)<div class="cm-dialog__description" id="{{ $id }}-description">{{ $descriptionContent }}</div>@elseif ($hasDescription)<p class="cm-dialog__description" id="{{ $id }}-description">{{ $descriptionContent }}</p>@endif<div class="cm-dialog__body">{{ $body }}</div>@if ($footer !== null)<footer class="cm-dialog__footer">{{ $footer }}</footer>@endif</div></dialog>
